114	#[comemo::memoize]
115	#[expect(clippy::too_many_arguments)]
116	fn layout_fragment_impl(
117	    world: Tracked<dyn World + '_>,
118	    library: &LazyHash<Library>,
119	    introspector: Tracked<dyn Introspector + '_>,
120	    traced: Tracked<Traced>,
121	    sink: TrackedMut<Sink>,
122	    route: Tracked<Route>,
123	    content: &Content,
124	    locator: Tracked<Locator>,
125	    styles: StyleChain,
126	    regions: Regions,
127	    column: ColumnOptions,
128	) -> SourceResult<Fragment> {
129	    if !regions.size.x.is_finite() && regions.expand.x {
130	        bail!(content.span(), "cannot expand into infinite width");
131	    }
132	    if !regions.size.y.is_finite() && regions.expand.y {
133	        bail!(content.span(), "cannot expand into infinite height");
134	    }
135	
136	    let introspector = Protected::from_raw(introspector);
137	    let link = LocatorLink::new(locator);
138	    let mut locator = Locator::link(&link).split();
139	    let mut engine = Engine {
140	        library,
141	        world,
142	        introspector,
143	        traced,
144	        sink,
145	        route: Route::extend(route),
146	    };
147	
148	    engine.route.check_layout_depth().at(content.span())?;
149	
150	    let mut kind = FragmentKind::Block;
151	    let arenas = Arenas::default();
152	    let children = (engine.library.routines.realize)(
153	        RealizationKind::Fragment { kind: &mut kind },
154	        &mut engine,
155	        &mut locator,
156	        &arenas,
157	        content,
158	        styles,
159	    )?;
160	
161	    layout_flow(
162	        &mut engine,
163	        &children,
164	        &mut locator,
165	        styles,
166	        regions,
167	        column,
168	        kind.into(),
169	    )
170	}
171	
172	/// The mode a flow can be laid out in.
173	#[derive(Debug, Copy, Clone, Eq, PartialEq)]
174	pub enum FlowMode {
175	    /// A root flow with block-level elements. Like `FlowMode::Block`, but can
176	    /// additionally host footnotes and line numbers.
177	    Root,
178	    /// A flow whose children are block-level elements.
179	    Block,
180	    /// A flow whose children are inline-level elements.
181	    Inline,
182	}
183	
184	impl From<FragmentKind> for FlowMode {
185	    fn from(value: FragmentKind) -> Self {
186	        match value {
187	            FragmentKind::Inline => Self::Inline,
188	            FragmentKind::Block => Self::Block,
189	        }
190	    }
191	}
192	
193	/// Lays out realized content into regions, potentially with columns.
194	pub fn layout_flow<'a>(
195	    engine: &mut Engine,
196	    children: &[Pair<'a>],
197	    locator: &mut SplitLocator<'a>,
198	    shared: StyleChain<'a>,
199	    mut regions: Regions,
200	    column: ColumnOptions,
201	    mode: FlowMode,
202	) -> SourceResult<Fragment> {
203	    // Prepare configuration that is shared across the whole flow.
204	    let config = configuration(shared, regions, column, mode);
205	
206	    // Collect the elements into pre-processed children. These are much easier
207	    // to handle than the raw elements.
208	    let bump = Bump::new();
209	    let children = collect(
210	        engine,
211	        &bump,
212	        children,
213	        locator.next(&()),
214	        Size::new(config.columns.width, regions.full),
215	        regions.expand.x,
216	        mode,
217	    )?;
218	
219	    let mut work = Work::new(&children);
220	    let mut finished = vec![];
221	
222	    // This loop runs once per region produced by the flow layout.
223	    loop {
224	        let frame = compose(engine, &mut work, &config, locator.next(&()), regions)?;
225	        finished.push(frame);
226	
227	        // Terminate the loop when everything is processed, though draining the
228	        // backlog if necessary.
229	        if work.done() && (!regions.expand.y || regions.backlog.is_empty()) {
230	            break;
231	        }
232	
233	        regions.next();
234	    }
235	
236	    Ok(Fragment::frames(finished))
237	}
238	
239	/// Determine the flow's configuration.
240	fn configuration<'x>(
241	    shared: StyleChain<'x>,
242	    regions: Regions,
243	    column: ColumnOptions,
244	    mode: FlowMode,
245	) -> Config<'x> {
246	    Config {
247	        mode,
248	        shared,
249	        columns: {
250	            let mut count = column.count.get();
251	            if !regions.size.x.is_finite() {
252	                count = 1;
253	            }
254	
255	            let gutter = column.gutter.relative_to(regions.base().x);
256	            let width = (regions.size.x - gutter * (count - 1) as f64) / count as f64;
257	            let dir = shared.resolve(TextElem::dir);
258	            ColumnConfig {
259	                count,
260	                width,
261	                gutter,
262	                dir,
263	                balanced: column.balanced,
264	            }
265	        },
266	        footnote: FootnoteConfig {
267	            separator: shared
268	                .get_cloned(FootnoteEntry::separator)
269	                .artifact(ArtifactKind::Other),
270	            clearance: shared.resolve(FootnoteEntry::clearance),
271	            gap: shared.resolve(FootnoteEntry::gap),
272	            expand: regions.expand.x,
273	        },

